function hills(col,base,amp,seed){cx.fillStyle=col;for(var x=0;x<W;x+=12){var h=base-Math.round((Math.sin(x*.011+seed)*amp+Math.sin(x*.027+seed*2)*amp*.5)/6)*6;cx.fillRect(x,h,12,H-h)}}
